const topRoutes = [
  { path: "/", label: "概览", icon: SquaresFour },
  { path: "/timeline", label: "时间线", icon: GitCommit },
  { path: "/projects", label: "项目", icon: FolderSimple },
  { path: "/resume", label: "履历", icon: Briefcase },
  { path: "/release", label: "人生版本", icon: Tag },
];

const typeMeta = {
  Life: { color: "green", icon: TreeEvergreen }, Project: { color: "blue", icon: Code },
  Learning: { color: "blue", icon: BookOpenText }, Idea: { color: "amber", icon: Lightbulb },
  Experience: { color: "green", icon: Briefcase }, Travel: { color: "amber", icon: AirplaneTilt },
  Milestone: { color: "blue", icon: GraduationCap },
};
const typeLabels = { Life: "生活", Project: "项目", Learning: "学习", Idea: "想法", Experience: "经历", Travel: "旅行", Milestone: "里程碑" };
const tabType = { 全部: null, 里程碑: ["Milestone", "Life"], 项目与经历: ["Project", "Experience"], 想法: ["Idea"], 学习: ["Learning"] };

function loadJson(key, fallback) {
  try { const saved = localStorage.getItem(key); return saved ? JSON.parse(saved) : fallback; }
  catch { return fallback; }
}

function formatLongDate(dateString) {
  return new Intl.DateTimeFormat("zh-CN", { month: "long", day: "numeric", year: "numeric", timeZone: "UTC" }).format(new Date(`${dateString}T00:00:00Z`));
}
function formatDateTime(value) {
  return new Intl.DateTimeFormat("zh-CN", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(value));
}
function formatBytes(value = 0) {
  if (value < 1024) return `${value} B`;
  if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KB`;
  return `${(value / 1024 / 1024).toFixed(1)} MB`;
}
function currentRoute() {
  const legacy = window.location.hash.replace("#", "");
  if (legacy) {
    const map = { overview: "/", timeline: "/timeline", repository: "/projects", release: "/release" };
    if (map[legacy]) window.history.replaceState(null, "", map[legacy]);
  }
  const path = window.location.pathname.replace(/\/+$/, "") || "/";
  if (path.startsWith("/projects/")) return { name: "project", slug: decodeURIComponent(path.slice(10)) };
  if (path === "/timeline") return { name: "timeline" };
  if (path === "/projects") return { name: "projects" };
  if (path === "/resume") return { name: "resume" };
  if (path === "/release") return { name: "release" };
  if (path === "/readme") return { name: "readme" };
  if (path === "/admin" || path === "/admin/projects") return { name: "admin-projects" };
  if (path === "/admin/readme") return { name: "admin-readme" };
  return { name: "overview" };
}
function navigate(path) {
  window.history.pushState(null, "", path);
  window.dispatchEvent(new PopStateEvent("popstate"));
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function AppHeader({ route, ownerMode, needsLogin, onOwnerToggle, onOpenSettings }) {
  const activePath = route.name === "overview" ? "/" : route.name === "project" ? "/projects" : `/${route.name}`;
  const enterFullscreen = () => document.fullscreenElement ? document.exitFullscreen?.() : document.documentElement.requestFullscreen?.();
  return (
    <header className="app-header">
      <button className="brand" type="button" onClick={() => navigate("/")}><TreeEvergreen size={32} weight="fill" /><span>LIFE GIT</span></button>
      <nav className="top-nav" aria-label="主导航">
        {topRoutes.map(({ path, label, icon: Icon }) => <button className={`nav-item ${activePath === path ? "is-active" : ""}`} key={path} type="button" onClick={() => navigate(path)}><Icon size={23} /><span>{label}</span></button>)}
      </nav>
      <div className="header-actions">
        <button className={`owner-switch ${ownerMode ? "is-owner" : ""}`} type="button" onClick={onOwnerToggle} title={needsLogin ? "使用 GitHub 登录" : ownerMode ? "切换为访客预览" : "进入 Tulip 管理台"}><UserCircle size={21} /><span>{needsLogin ? "GitHub 登录" : ownerMode ? "管理中" : "访客"}</span></button>
        <button className="icon-button" aria-label="设置" title="设置" onClick={onOpenSettings} type="button"><Gear size={23} /></button>
        <button className="icon-button" aria-label="切换全屏" title="切换全屏" onClick={enterFullscreen} type="button"><CornersOut size={23} /></button>
      </div>
    </header>
  );
}

